<script setup lang="ts">
import { computed, ref, useId, watch, type Component } from 'vue'
import { useRoute, type RouteLocationRaw } from 'vue-router'
import { useAccountPreferences } from '../../preferences/store'
import type { Workspace } from '../../preferences/schema'
import NavigationItem from './NavigationItem.vue'
import UiPopover from '../UiPopover.vue'
export type CustomNavigationItem={id:string;to:RouteLocationRaw;label:string;icon?:Component;active?:boolean}
const props=defineProps<{workspace:Workspace;items:CustomNavigationItem[]}>()
const store=useAccountPreferences(),anchor=ref<HTMLElement|null>(null),open=ref(false)
const route=useRoute(),popoverId=useId()
watch(()=>route.fullPath,()=>{open.value=false})
const config=computed(()=>store.values[`sidebar.${props.workspace}`])
const ordered=computed(()=>config.value.order.map(id=>props.items.find(item=>item.id===id)).filter((item):item is CustomNavigationItem=>!!item))
const primary=computed(()=>ordered.value.filter(item=>!config.value.hidden.includes(item.id)))
const tools=computed(()=>ordered.value.filter(item=>config.value.hidden.includes(item.id)))
const toolActive=computed(()=>tools.value.some(item=>item.active))
function expanded(group:string){return !config.value.collapsed_groups.includes(group)}
function toggle(group:string){store.set(`sidebar.${props.workspace}`,{...config.value,collapsed_groups:expanded(group)?[...config.value.collapsed_groups,group]:config.value.collapsed_groups.filter(id=>id!==group)})}
</script>
<template><nav class="custom-navigation" aria-label="常用页面"><button type="button" class="navigation-group-toggle" :aria-expanded="expanded('primary')" @click="toggle('primary')"><span>{{ store.values.language==='en'?'Pinned':'常用页面' }}</span><span aria-hidden="true">{{ expanded('primary')?'⌄':'›' }}</span></button><div v-show="expanded('primary')"><NavigationItem v-for="item in primary" :key="item.id" :to="item.to" :label="item.label" :icon="item.icon" :active="item.active"/></div></nav><button ref="anchor" type="button" class="navigation-more" :class="{active:toolActive}" aria-haspopup="dialog" :aria-expanded="open" :aria-controls="open?popoverId:undefined" @click="open=!open"><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="4" cy="10" r="1.4"/><circle cx="10" cy="10" r="1.4"/><circle cx="16" cy="10" r="1.4"/></svg><span>{{ store.values.language==='en'?'More tools':'更多工具' }}</span></button><UiPopover v-model:open="open" :anchor="anchor" :id="popoverId" role="dialog" :label="store.values.language==='en'?'More tools':'更多工具'"><nav class="custom-navigation-tools"><template v-for="group in ['tools','subjects']" :key="group"><template v-if="tools.some(item=>(group==='subjects')===item.id.startsWith('subject-'))"><button type="button" class="navigation-group-toggle" :aria-expanded="expanded(group)" @click="toggle(group)"><span>{{ store.values.language==='en'?(group==='subjects'?'Subjects':'Tools'):(group==='subjects'?'科目':'工具') }}</span><span aria-hidden="true">{{ expanded(group)?'⌄':'›' }}</span></button><div v-show="expanded(group)"><NavigationItem v-for="item in tools.filter(item=>(group==='subjects')===item.id.startsWith('subject-'))" :key="item.id" :to="item.to" :label="item.label" :icon="item.icon" :active="item.active" @click="open=false"/></div></template></template><RouterLink class="navigation-customize-link" to="/settings?section=sidebar" @click="open=false">{{ store.values.language==='en'?'Customize sidebar':'自定义侧栏' }}</RouterLink></nav></UiPopover></template>
<style scoped>.navigation-group-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:36px;padding:8px 10px;border:0;background:transparent;color:var(--text-secondary);font:500 12px var(--font-ui);cursor:pointer}.navigation-more{display:flex;align-items:center;gap:8px;min-height:44px;width:100%;margin-top:8px;border:0;border-radius:6px;padding:8px 10px;background:transparent;color:var(--text-secondary);font:inherit;text-align:left;cursor:pointer}.navigation-more:hover,.navigation-more.active{background:var(--surface-selected);color:var(--text-primary)}.navigation-more svg{width:16px;height:16px;fill:currentColor;flex:none}.custom-navigation-tools{width:272px;max-width:100%;padding:4px;min-width:0}.navigation-customize-link{display:flex;align-items:center;min-height:44px;font-size:13px;color:var(--text-secondary);padding:8px 10px;text-decoration:none;border-top:1px solid var(--border-subtle)}@media(pointer:coarse){.navigation-group-toggle{min-height:44px}}</style>
